begin;
create extension if not exists pgtap;
select plan(171);
select has_table('operations','return_claims','claim header exists');
select has_table('operations','return_claim_items','claim item snapshot exists');
select has_table('operations','return_claim_events','immutable claim history exists');
select has_column('operations','return_claims','external_claim_ref','external claim reference is stored');
select has_column('operations','return_claims','claim_basis_code','basis code is stored');
select has_column('operations','return_claims','claim_basis_at','basis timestamp is stored');
select has_column('operations','return_claims','window_days_snapshot','window snapshot is stored');
select has_column('operations','return_claims','timezone_snapshot','timezone snapshot is stored');
select has_column('operations','return_claims','deadline_source_code','deadline source is stored');
select has_column('operations','return_claims','deadline_at','exact deadline is stored');
select has_column('operations','return_claims','request_hash','normalized request hash is stored');
select has_column('operations','return_claim_items','canonical_components_snapshot','canonical historical component snapshot is stored');
select has_index('operations','return_claims','idx_return_claim_deadline','deadline lookup index exists');
select has_index('operations','return_claims','uidx_return_claim_external_ref','external reference uniqueness index exists');
select ok(exists(select 1 from pg_constraint where conrelid='operations.return_claims'::regclass and conname='ck_return_claim_tiktok_policy'),'TikTok return-created-at policy constraint exists');
select ok(exists(select 1 from pg_constraint where conrelid='operations.return_claim_items'::regclass and conname='ck_return_claim_items_qty'),'positive and capped item quantity constraint exists');
select ok(exists(select 1 from pg_constraint where conrelid='operations.return_claims'::regclass and conname='ck_return_claim_status'),'status transition domain constraint exists');
select ok(exists(select 1 from pg_constraint where conrelid='operations.return_claims'::regclass and conname='ck_return_claim_resolution'),'resolution domain constraint exists');
select has_view('api','return_claim_master','safe claim master read model exists');
select has_view('api','return_claim_items','safe claim item read model exists');
select has_view('api','return_claim_events','safe claim event read model exists');
select has_function('api','create_tiktok_return_claim',array['uuid','text','uuid','text','jsonb','timestamp with time zone'],'trusted create RPC exists');
select has_function('api','submit_tiktok_return_claim',array['uuid','text','uuid','text','timestamp with time zone'],'submit RPC exists');
select has_function('api','resolve_tiktok_return_claim',array['uuid','text','uuid','text','timestamp with time zone'],'resolve RPC exists');
select has_function('api','cancel_tiktok_return_claim',array['uuid','text','uuid','text','timestamp with time zone'],'cancel RPC exists');
select has_function('api','evaluate_tiktok_return_claim_deadline',array['uuid','text','uuid','timestamp with time zone'],'deadline evaluator command exists');
select ok((select relrowsecurity from pg_class where oid='operations.return_claims'::regclass),'claim RLS is enabled');
select ok((select relrowsecurity from pg_class where oid='operations.return_claim_items'::regclass),'claim item RLS is enabled');
select ok((select relrowsecurity from pg_class where oid='operations.return_claim_events'::regclass),'claim event RLS is enabled');
select ok(not has_table_privilege('authenticated','operations.return_claims','INSERT'),'authenticated cannot write claim header directly');
select ok(not has_table_privilege('authenticated','operations.return_claim_items','INSERT'),'authenticated cannot write claim items directly');
select ok(not has_table_privilege('authenticated','operations.return_claim_events','INSERT'),'authenticated cannot append claim events directly');
select ok(has_function_privilege('authenticated','api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)','EXECUTE'),'authenticated may invoke public create RPC');
select ok(has_function_privilege('authenticated','api.submit_tiktok_return_claim(uuid,text,uuid,text,timestamp with time zone)','EXECUTE'),'authenticated may invoke public submit RPC');
select ok(not has_function_privilege('authenticated','api.transition_tiktok_return_claim(uuid,text,uuid,text,text,text,text,timestamp with time zone)','EXECUTE'),'authenticated cannot invoke internal transition helper');
select ok(not has_function_privilege('anon','api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)','EXECUTE'),'anonymous users cannot execute create RPC');
select ok((select procedure.prosecdef from pg_proc procedure where procedure.oid='api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'create RPC is SECURITY DEFINER');
select ok((select procedure.prosecdef from pg_proc procedure where procedure.oid='api.transition_tiktok_return_claim(uuid,text,uuid,text,text,text,text,timestamp with time zone)'::regprocedure),'transition helper is SECURITY DEFINER');
select matches(coalesce((select array_to_string(procedure.proconfig,',') from pg_proc procedure where procedure.oid='api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),''),'^search_path=pg_catalog, auth, app, operations, inventory, catalog, extensions$','create RPC has fixed search_path');
select matches(coalesce((select array_to_string(procedure.proconfig,',') from pg_proc procedure where procedure.oid='api.transition_tiktok_return_claim(uuid,text,uuid,text,text,text,text,timestamp with time zone)'::regprocedure),''),'^search_path=pg_catalog, auth, app, operations, inventory, extensions$','transition helper has fixed search_path');
select ok(exists(select 1 from pg_trigger where tgrelid='operations.return_claim_events'::regclass and tgname='trg_return_claim_events_immutable'),'claim events have append-only trigger');
select ok(exists(select 1 from pg_trigger where tgrelid='operations.return_claim_items'::regclass and tgname='trg_return_claim_items_immutable'),'claim items have immutable snapshot trigger');
select ok(exists(select 1 from pg_trigger where tgrelid='operations.return_claims'::regclass and tgname='trg_return_claims_snapshot_immutable'),'claim deadline-policy snapshot has immutable trigger');
select matches(pg_get_functiondef('api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'RETURN_CREATED_AT','create uses return-created timestamp basis');
select matches(pg_get_functiondef('api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'Asia/Jakarta','create snapshots Asia/Jakarta timezone');
select matches(pg_get_functiondef('api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'interval ''40 days''','create stores forty calendar-day deadline');
select matches(pg_get_functiondef('api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'TIKTOK_SHOP','Shopee and other channels cannot inherit TikTok policy');
select matches(pg_get_functiondef('api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'RETURN_CLAIM_DUPLICATE_ITEM','partial item command rejects duplicate canonical lines');
select matches(pg_get_functiondef('api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'RETURN_CLAIM_ITEM_NOT_ELIGIBLE','zero negative fraction and over-claim inputs are rejected');
select matches(pg_get_functiondef('api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'snapshotSchemaVersion','claim snapshot separates its schema version from source provenance');
select matches(pg_get_functiondef('api.create_tiktok_return_claim(uuid,text,uuid,text,jsonb,timestamp with time zone)'::regprocedure),'IDEMPOTENCY_KEY_REUSED','identical replay is idempotent and changed payload conflicts');
select matches(pg_get_functiondef('api.transition_tiktok_return_claim(uuid,text,uuid,text,text,text,text,timestamp with time zone)'::regprocedure),'RETURN_CLAIM_SUBMIT_INVALID','submit transition is guarded');
select matches(pg_get_functiondef('api.transition_tiktok_return_claim(uuid,text,uuid,text,text,text,text,timestamp with time zone)'::regprocedure),'RETURN_CLAIM_RESOLVE_INVALID','resolve transition is guarded');
select matches(pg_get_functiondef('api.transition_tiktok_return_claim(uuid,text,uuid,text,text,text,text,timestamp with time zone)'::regprocedure),'RETURN_CLAIM_CANCEL_INVALID','cancel transition is guarded');
select matches(pg_get_functiondef('api.transition_tiktok_return_claim(uuid,text,uuid,text,text,text,text,timestamp with time zone)'::regprocedure),'stockEffectCode','all claim commands declare stock-neutral effect');

create temp table claim_behavior_results(kind text primary key, result jsonb not null) on commit drop;
grant select, insert, update on claim_behavior_results to authenticated;
create temp table claim_auth_fixture(admin_user_id uuid primary key) on commit drop;
insert into auth.users(instance_id,id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,is_sso_user,is_anonymous) values
  ('00000000-0000-0000-0000-000000000000','95500000-0000-4000-8000-000000000055','authenticated','authenticated','pgtap.claim.055.admin@glowlab.invalid','2026-06-01 00:00:00+07','{"provider":"email","providers":["email"]}'::jsonb,'{}'::jsonb,'2026-06-01 00:00:00+07','2026-06-01 00:00:00+07',false,false);
insert into app.user_profiles(user_id,organization_id,display_name,employee_code,role_code,is_active) values
  ('95500000-0000-4000-8000-000000000055','00000000-0000-4000-8000-000000000001','pgTAP Claim 055 Admin','PGTAP-CLAIM-055','ADMIN',true);
insert into claim_auth_fixture values ('95500000-0000-4000-8000-000000000055');
select set_config('request.jwt.claim.sub',(select admin_user_id::text from claim_auth_fixture),true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select admin_user_id::text from claim_auth_fixture),'role','authenticated')::text,true);
set local role authenticated;
insert into claim_behavior_results select 'RESERVE',api.apply_marketplace_event('00000000-0000-4000-8000-000000000001','055-TT-RESERVE','TIKTOK_SHOP','RESERVE','055-TT-RESERVE-EVENT','055-TT-ORDER','2026-06-01 09:00:00+07',jsonb_build_array(jsonb_build_object('productId','30000000-0000-4000-8000-000000000001','quantity',2,'sourceLineRef','055-TT-LINE')),'fixture','{}');
insert into claim_behavior_results select 'SHIP',api.apply_marketplace_event('00000000-0000-4000-8000-000000000001','055-TT-SHIP','TIKTOK_SHOP','SHIP','055-TT-SHIP-EVENT','055-TT-ORDER','2026-06-02 09:00:00+07',jsonb_build_array(jsonb_build_object('productId','30000000-0000-4000-8000-000000000001','quantity',2,'sourceLineRef','055-TT-LINE')),'fixture','{}');
insert into claim_behavior_results select 'EXPECTED',api.create_expected_return('00000000-0000-4000-8000-000000000001','055-TT-EXPECTED','TIKTOK_SHOP','055-TT-RETURN','055-TT-ORDER','2026-06-03 10:00:00+07',jsonb_build_array(jsonb_build_object('productId','30000000-0000-4000-8000-000000000001','quantity',2,'sourceLineRef','055-TT-LINE')),'RETURN_REQUESTED','fixture','{}');
insert into claim_behavior_results select 'LOST',api.mark_return_lost('00000000-0000-4000-8000-000000000001','055-TT-LOST','055-TT-RETURN','055-TT-LOST-EVENT','2026-06-04 11:00:00+07',jsonb_build_array(jsonb_build_object('returnItemId',(select item.id::text from operations.return_items item join operations.returns header on header.id=item.return_id where header.external_return_ref='055-TT-RETURN'),'quantity',1,'sourceLineRef','055-TT-LOST-LINE')),'fixture','{}');
create temp table claim_stock_before as select count(*)::bigint transaction_count from inventory.stock_transactions where organization_id='00000000-0000-4000-8000-000000000001'::uuid;
insert into claim_behavior_results select 'CREATE',api.create_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-CLAIM',(select id from operations.returns where external_return_ref='055-TT-RETURN'),'LOST_RETURN',jsonb_build_array(jsonb_build_object('returnItemId',(select item.id::text from operations.return_items item join operations.returns header on header.id=item.return_id where header.external_return_ref='055-TT-RETURN'),'quantity',1)),'2026-06-20 10:00:00+07');
insert into claim_behavior_results select 'REPLAY',api.create_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-CLAIM',(select id from operations.returns where external_return_ref='055-TT-RETURN'),'LOST_RETURN',jsonb_build_array(jsonb_build_object('returnItemId',(select item.id::text from operations.return_items item join operations.returns header on header.id=item.return_id where header.external_return_ref='055-TT-RETURN'),'quantity',1)),'2026-06-20 10:00:00+07');
reset role;
select is((select result->>'status' from claim_behavior_results where kind='RESERVE'),'APPLIED','trusted TikTok reservation is applied');
select is((select result->>'status' from claim_behavior_results where kind='SHIP'),'APPLIED','trusted TikTok shipment is applied');
select is((select result->>'status' from claim_behavior_results where kind='EXPECTED'),'EXPECTED','trusted expected return is created');
select is((select result->>'status' from claim_behavior_results where kind='LOST'),'PARTIALLY_RECEIVED','trusted partial lost event is created');
select is((select count(*) from operations.return_claims where return_id=(select id from operations.returns where external_return_ref='055-TT-RETURN')),1::bigint,'one claim is created from canonical TikTok return item');
select is((select quantity from operations.return_claim_items where claim_id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE')),1::bigint,'claim quantity equals eligible partial lost quantity');
select is((select deadline_at from operations.return_claims where id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE')),(select created_at + interval '40 days' from operations.returns where external_return_ref='055-TT-RETURN'),'deadline is exactly forty calendar days after return created_at');
select is((select timezone_snapshot from operations.return_claims where id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE')),'Asia/Jakarta','deadline policy snapshots Jakarta timezone');
select is((select result->>'claimId' from claim_behavior_results where kind='CREATE'),(select result->>'claimId' from claim_behavior_results where kind='REPLAY'),'identical create replay returns same claim');
select is((select count(*) from operations.return_claim_events where claim_id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE')),1::bigint,'identical replay does not duplicate claim event');
select is((select count(*) from inventory.stock_transactions where organization_id='00000000-0000-4000-8000-000000000001'::uuid),(select transaction_count from claim_stock_before),'claim creation is stock-transaction neutral');
select throws_ok($$select api.create_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-CLAIM',(select id from operations.returns where external_return_ref='055-TT-RETURN'),'LOST_RETURN',jsonb_build_array(jsonb_build_object('returnItemId',(select item.id::text from operations.return_items item join operations.returns header on header.id=item.return_id where header.external_return_ref='055-TT-RETURN'),'quantity',2)),'2026-06-20 10:00:00+07')$$,'P0001','IDEMPOTENCY_KEY_REUSED','changed idempotency payload is rejected');
select throws_ok($$update operations.return_claim_events set note='mutated' where claim_id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE')$$,'P0001','RETURN_CLAIM_HISTORY_IMMUTABLE','claim event history cannot be edited');
select throws_ok($$select api.create_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-OVER',(select id from operations.returns where external_return_ref='055-TT-RETURN'),'LOST_RETURN',jsonb_build_array(jsonb_build_object('returnItemId',(select item.id::text from operations.return_items item join operations.returns header on header.id=item.return_id where header.external_return_ref='055-TT-RETURN'),'quantity',2)),'2026-06-20 10:00:00+07')$$,'P0001','RETURN_CLAIM_ITEM_CAPACITY_EXCEEDED','over-claim is rejected');
create temp table claim_lifecycle_stock_before as select (select count(*) from inventory.stock_transactions where organization_id='00000000-0000-4000-8000-000000000001'::uuid)::bigint transaction_count,(select count(*) from inventory.stock_ledger_entries where organization_id='00000000-0000-4000-8000-000000000001'::uuid)::bigint ledger_count;
select set_config('request.jwt.claim.sub',(select admin_user_id::text from claim_auth_fixture),true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select admin_user_id::text from claim_auth_fixture),'role','authenticated')::text,true);
set local role authenticated;
insert into claim_behavior_results select 'SUBMIT',api.submit_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-SUBMIT',(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE'),'TT-CLAIM-055','2026-06-21 10:00:00+07');
insert into claim_behavior_results select 'SUBMIT_REPLAY',api.submit_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-SUBMIT',(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE'),'TT-CLAIM-055','2026-06-21 10:00:00+07');
insert into claim_behavior_results select 'RESOLVE',api.resolve_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-RESOLVE',(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE'),'APPROVED','2026-06-22 10:00:00+07');
reset role;
select is((select status_code from operations.return_claims where id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE')),'RESOLVED','submit then resolve reaches RESOLVED');
select is((select count(*) from operations.return_claim_events where claim_id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE') and event_type_code='SUBMITTED'),1::bigint,'submit replay appends only one submitted event');
select is((select count(*) from operations.return_claim_events where claim_id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE') and event_type_code='RESOLVED'),1::bigint,'resolve appends immutable resolved event');
select ok((select submitted_at is not null and resolved_at is not null and actor_user_id=(select admin_user_id from claim_auth_fixture) from operations.return_claims where id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE')),'lifecycle persists actor and timestamps');
select is((select count(*) from inventory.stock_transactions where organization_id='00000000-0000-4000-8000-000000000001'::uuid),(select transaction_count from claim_lifecycle_stock_before),'submit and resolve are stock-transaction neutral');
select is((select count(*) from inventory.stock_ledger_entries where organization_id='00000000-0000-4000-8000-000000000001'::uuid),(select ledger_count from claim_lifecycle_stock_before),'submit and resolve are ledger neutral');
select throws_ok($$select api.cancel_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-TERMINAL',(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE'),'terminal','2026-06-23 10:00:00+07')$$,'P0001','RETURN_CLAIM_CANCEL_INVALID','terminal claim cannot be cancelled');
create temp table cancel_stock_before as select (select count(*) from inventory.stock_transactions)::bigint transaction_count,(select count(*) from inventory.stock_ledger_entries)::bigint ledger_count;
select set_config('request.jwt.claim.sub',(select admin_user_id::text from claim_auth_fixture),true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select admin_user_id::text from claim_auth_fixture),'role','authenticated')::text,true);
set local role authenticated;
insert into claim_behavior_results select 'LOST_CANCEL',api.mark_return_lost('00000000-0000-4000-8000-000000000001','055-TT-LOST-CANCEL','055-TT-RETURN','055-TT-LOST-CANCEL-EVENT','2026-06-05 11:00:00+07',jsonb_build_array(jsonb_build_object('returnItemId',(select item.id::text from operations.return_items item join operations.returns header on header.id=item.return_id where header.external_return_ref='055-TT-RETURN'),'quantity',1,'sourceLineRef','055-TT-LOST-CANCEL-LINE')),'fixture','{}');
insert into claim_behavior_results select 'CREATE_CANCEL',api.create_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-CLAIM-CANCEL',(select id from operations.returns where external_return_ref='055-TT-RETURN'),'LOST_RETURN',jsonb_build_array(jsonb_build_object('returnItemId',(select item.id::text from operations.return_items item join operations.returns header on header.id=item.return_id where header.external_return_ref='055-TT-RETURN'),'quantity',1)),'2026-06-20 10:00:00+07');
insert into claim_behavior_results select 'CANCEL',api.cancel_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-CANCEL',(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE_CANCEL'),'customer withdrew claim','2026-06-21 10:00:00+07');
insert into claim_behavior_results select 'CANCEL_REPLAY',api.cancel_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-CANCEL',(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE_CANCEL'),'customer withdrew claim','2026-06-21 10:00:00+07');
reset role;
select is((select status_code from operations.return_claims where id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE_CANCEL')),'CANCELLED','open claim is cancelled through trusted RPC');
select ok((select cancelled_at is not null and actor_user_id=(select admin_user_id from claim_auth_fixture) from operations.return_claims where id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE_CANCEL')),'cancel records actor and timestamp');
select is((select count(*) from operations.return_claim_events where claim_id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE_CANCEL') and event_type_code='CANCELLED'),1::bigint,'cancel replay appends one cancel event');
select is((select count(*) from operations.return_claim_events where claim_id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE_CANCEL') and event_type_code='CREATED'),1::bigint,'cancel preserves create history');
select throws_ok($$select api.cancel_tiktok_return_claim('00000000-0000-4000-8000-000000000001','055-TT-CANCEL-CHANGED',(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE_CANCEL'),'','2026-06-21 10:00:00+07')$$,'P0001','RETURN_CLAIM_CANCEL_INVALID','cancel requires reason');
select is((select count(*) from inventory.stock_transactions),(select transaction_count from cancel_stock_before),'cancel scenario is stock-transaction neutral');
select is((select count(*) from inventory.stock_ledger_entries),(select ledger_count from cancel_stock_before),'cancel scenario is ledger neutral');
insert into app.organizations(id,code,name,timezone,is_active,created_at) values('00000000-0000-4000-8000-000000000055','PGTAP_CLAIM_055_B','pgTAP Claim Isolation B','Asia/Jakarta',true,clock_timestamp());
insert into auth.users(instance_id,id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,is_sso_user,is_anonymous) values('00000000-0000-0000-0000-000000000000','95500000-0000-4000-8000-000000000001','authenticated','authenticated','pgtap.claim.055.b@invalid',clock_timestamp(),'{"provider":"email","providers":["email"]}','{}',clock_timestamp(),clock_timestamp(),false,false);
insert into app.user_profiles(user_id,organization_id,display_name,employee_code,role_code,is_active) values('95500000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000055','pgTAP Claim Admin B','PGTAP-055-B','ADMIN',true);
select set_config('request.jwt.claim.sub','95500000-0000-4000-8000-000000000001',true); select set_config('request.jwt.claim.role','authenticated',true); select set_config('request.jwt.claims','{"sub":"95500000-0000-4000-8000-000000000001","role":"authenticated"}',true); set local role authenticated;
select is((select count(*) from api.return_claim_master where id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE')),0::bigint,'organization B cannot read organization A claim through safe view');
select throws_ok($$select api.submit_tiktok_return_claim('00000000-0000-4000-8000-000000000055','055-B-FOREIGN',(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE'),'foreign-ref',clock_timestamp())$$,'P0001','RETURN_CLAIM_NOT_FOUND','organization B cannot submit foreign claim');
reset role;
select is((select count(*) from operations.return_claim_events where claim_id=(select (result->>'claimId')::uuid from claim_behavior_results where kind='CREATE') and event_type_code='SUBMITTED'),1::bigint,'foreign rejection leaves original claim history unchanged');
select is((select count(*) from inventory.idempotency_commands where organization_id='00000000-0000-4000-8000-000000000055'::uuid and scope='TIKTOK_RETURN_CLAIM_SUBMIT'),0::bigint,'foreign rejection leaves no idempotency command');
select set_config('request.jwt.claim.sub',(select admin_user_id::text from claim_auth_fixture),true); select set_config('request.jwt.claim.role','authenticated',true); select set_config('request.jwt.claims',jsonb_build_object('sub',(select admin_user_id::text from claim_auth_fixture),'role','authenticated')::text,true); set local role authenticated;
insert into claim_behavior_results select 'EXP_RESERVE',api.apply_marketplace_event('00000000-0000-4000-8000-000000000001','055-EXP-RESERVE','TIKTOK_SHOP','RESERVE','055-EXP-RESERVE-EVENT','055-EXP-ORDER','2026-05-01 09:00:00+07',jsonb_build_array(jsonb_build_object('productId','30000000-0000-4000-8000-000000000002','quantity',1,'sourceLineRef','055-EXP-LINE')),'fixture','{}');
