create temp table multi_atomic_before as
select jsonb_build_object(
  'claims',
  (select count(*) from operations.return_claims where return_id = (select return_id from multi_success_fixture)),
  'claimItems',
  (select count(*) from operations.return_claim_items item join operations.return_claims claim on claim.id = item.claim_id and claim.organization_id = item.organization_id where claim.return_id = (select return_id from multi_success_fixture)),
  'claimEvents',
  (select count(*) from operations.return_claim_events event join operations.return_claims claim on claim.id = event.claim_id and claim.organization_id = event.organization_id where claim.return_id = (select return_id from multi_success_fixture)),
  'outbox',
  (select count(*) from notification.outbox_events outbox join operations.return_claims claim on claim.id = outbox.entity_id and claim.organization_id = outbox.organization_id where claim.return_id = (select return_id from multi_success_fixture)),
  'commands',
  (select count(*) from inventory.idempotency_commands where organization_id = '00000000-0000-4000-8000-000000000001'::uuid and scope = 'CREATE_TIKTOK_RETURN_CLAIM' and key = '055-MULTI-ATOMIC'),
  'successfulCommands',
  (select count(*) from inventory.idempotency_commands where organization_id = '00000000-0000-4000-8000-000000000001'::uuid and scope = 'CREATE_TIKTOK_RETURN_CLAIM' and key = '055-MULTI-ATOMIC' and status_code = 'SUCCEEDED'),
  'stockTransactions',
  (select count(*) from inventory.stock_transactions),
  'ledgerEntries',
  (select count(*) from inventory.stock_ledger_entries),
  'productProjection',
  (select coalesce(jsonb_agg(to_jsonb(product) order by product.product_id), '[]'::jsonb) from inventory.stock_product_positions product),
  'batchProjection',
  (select coalesce(jsonb_agg(to_jsonb(batch) order by batch.product_id, batch.batch_id), '[]'::jsonb) from inventory.stock_batch_balances batch),
  'reservations',
  (select coalesce(jsonb_agg(to_jsonb(reservation) order by reservation.id), '[]'::jsonb) from inventory.stock_reservations reservation)
) snapshot;
