);

select is((select jsonb_agg(jsonb_build_object('sourceLineId',snapshot.component->>'marketplaceSourceLineId','mappingVersion',snapshot.component->'mappingVersion','bundleRecipeId',snapshot.component->>'bundleRecipeId','recipeComponentId',snapshot.component->>'recipeComponentId','componentNo',snapshot.component->'componentNo','unitQuantityPerListing',snapshot.component->'unitQuantityPerListing','expandedQuantity',snapshot.component->'expandedQuantity') order by item.product_id) from operations.return_claim_items item cross join lateral jsonb_array_elements(item.canonical_components_snapshot) snapshot(component) where item.claim_id=(select (result->>'claimId')::uuid from bundle_history_results where kind='CLAIM')),(select jsonb_agg(jsonb_build_object('sourceLineId',source_line.id::text,'mappingVersion',to_jsonb(source_line.mapping_version),'bundleRecipeId',source_line.bundle_recipe_id::text,'recipeComponentId',component.recipe_component_id::text,'componentNo',to_jsonb(component.component_no),'unitQuantityPerListing',to_jsonb(component.unit_quantity_per_listing),'expandedQuantity',to_jsonb(component.expanded_quantity)) order by component.product_id) from operations.marketplace_source_line_components component join operations.marketplace_source_lines source_line on source_line.organization_id=component.organization_id and source_line.id=component.source_line_id where source_line.order_id=(select id from operations.marketplace_orders where external_order_ref='055-HIST-ORDER')),'claim snapshot stores the immutable V1 source-line, mapping, recipe, and component provenance');
select ok(not exists(select 1 from operations.return_claim_items item cross join lateral jsonb_array_elements(item.canonical_components_snapshot) snapshot(component) where item.claim_id=(select (result->>'claimId')::uuid from bundle_history_results where kind='CLAIM') and snapshot.component->>'bundleRecipeId'=(select result->>'versionId' from bundle_history_results where kind='V2_ACTIVE')),'claim snapshot does not replace historical V1 provenance with current V2');
select is((select canonical_components_snapshot from api.return_claim_items where claim_id=(select (result->>'claimId')::uuid from bundle_history_results where kind='CLAIM') order by product_id limit 1),(select canonical_components_snapshot from operations.return_claim_items where claim_id=(select (result->>'claimId')::uuid from bundle_history_results where kind='CLAIM') order by product_id limit 1),'safe claim-item read model exposes the immutable provenance snapshot');
select * from finish();
rollback;
